function SamlForgePure(){
  function b64dec(s){
    s=(s||'').replace(/[^A-Za-z0-9+/=]/g,'');
    try { return decodeURIComponent(escape(atob(s))); } catch(e){ return null; }
  }
  function tagText(xml, tag){
    var re=new RegExp('<(?:[\\w]+:)?'+tag+'\\b[^>]*>([\\s\\S]*?)<\\/(?:[\\w]+:)?'+tag+'>');
    var m=xml.match(re); return m?m[1].trim():null;
  }
  function tagAttr(xml, tag, attr){
    var re=new RegExp('<(?:[\\w]+:)?'+tag+'\\b[^>]*\\b'+attr+'="([^"]*)"');
    var m=xml.match(re); return m?m[1]:null;
  }
  function tagAll(xml, tag){
    var re=new RegExp('<(?:[\\w]+:)?'+tag+'\\b[^>]*>([\\s\\S]*?)<\\/(?:[\\w]+:)?'+tag+'>','g');
    var out=[],m; while((m=re.exec(xml))) out.push(m[1].trim()); return out;
  }
  function analyze(input){
    var s=(input||'').trim();
    if(!s) return {error:'请输入 SAML Response（XML 原文，或 base64 编码）'};
    var xml;
    if(s.charAt(0)==='<'){ xml=s; }
    else if(/^[A-Za-z0-9+/=\r\n]+$/.test(s)){
      var dec=b64dec(s);
      if(!dec) return {error:'Base64 解码失败'};
      if(dec.charAt(0)==='<'){ xml=dec; }
      else if(dec.charCodeAt(0)===0x78){ return {error:'检测到 Deflate 压缩载荷（HTTP-Redirect 绑定）。请先解压为 XML 再粘贴（POST 绑定的 base64 XML 可直接解析）。'}; }
      else return {error:'Base64 解码后不是 XML'};
    } else return {error:'无法识别的输入：应为 XML 或 Base64'};
    if(xml.indexOf('<')<0) return {error:'内容中未找到 XML 标签'};
    var issuer=tagText(xml,'Issuer');
    var nameId=tagText(xml,'NameID');
    var nb=tagAttr(xml,'Conditions','NotBefore');
    var na=tagAttr(xml,'Conditions','NotOnOrAfter');
    var audience=tagAll(xml,'Audience');
    var dest=tagAttr(xml,'Response','Destination')||tagAttr(xml,'Assertion','Destination');
    var attrs=[];
    var are=/<(?:[\w]+:)?Attribute\b[^>]*\bName="([^"]*)"[^>]*>([\s\S]*?)<\/(?:[\w]+:)?Attribute>/g;
    var am; while((am=are.exec(xml))){ attrs.push({name:am[1], values:tagAll(am[2],'AttributeValue')}); }
    var sig=tagText(xml,'SignatureValue');
    var now=new Date();
    function t(x){ if(!x) return null; var d=new Date(x); return isNaN(d)?null:d; }
    var a=t(nb), b=t(na);
    var valid=(!a||now>=a)&&(!b||now<=b);
    var validMsg=valid?'当前在有效期内':(a&&now<a?'尚未生效 (NotBefore '+nb+')':'已过期 (NotOnOrAfter '+na+')');
    return {error:null, xml:xml, info:{
      issuer:issuer, nameId:nameId, notBefore:nb, notOnOrAfter:na,
      audience:audience, destination:dest, attributes:attrs,
      signed:!!sig, valid:valid, validMsg:validMsg
    }};
  }
  var api={analyze:analyze};
  if(typeof window!=='undefined'){ window.__PURE__=api; }
  if(typeof module!=='undefined'&&module.exports){ module.exports={SamlForgePure:SamlForgePure}; }
  return api;
}
